package com.guocheng.mediapocket;
import java.net.*;import java.io.*;import org.json.*;
final class TvBoxNet {
 static String fetch(String address,JSONObject body,String ua)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(TvBoxRules.resolve(address,address)).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent",ua==null||ua.isEmpty()?"Mozilla/5.0":ua);c.setRequestProperty("Accept","application/json, text/plain, */*");try{if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");try(OutputStream o=c.getOutputStream()){o.write(body.toString().getBytes("UTF-8"));}}int code=c.getResponseCode();if(code<200||code>=300)throw new IOException("接口返回 HTTP "+code);try(InputStream in=c.getInputStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new IOException("请求已取消");if(bytes.size()+n>8*1024*1024)throw new IOException("列表过大，请使用较小的配置或直播列表");bytes.write(b,0,n);}return bytes.toString("UTF-8");}}finally{c.disconnect();}}
 static JSONObject alist(String server,String action,JSONObject args)throws Exception{JSONObject r=new JSONObject(fetch(server.replaceAll("/+$","")+"/api/fs/"+action,args,null));if(r.optInt("code")!=200)throw new IOException(r.optString("message","小雅接口不可用"));JSONObject data=r.optJSONObject("data");if(data==null)throw new IOException("接口未返回目录数据");return data;}
}
